{
    int seconds = 0;
    /* read seconds, then print */
    return 0;
}

exercises.solution:
#include <stdio.h>

int main(void)
{
    int seconds = 0;
    scanf("%d", &seconds);
    printf("%d min %d s\n", seconds / 60, seconds % 60);
    return 0;
}

